//! The bundled emulator catalog: `assets/emulators.json`, generated by
//! `tools/build_catalog.py` from ES-DE's system definitions and libretro's core info files.
//! Loaded into SQLite at startup so the UI can query it.

use anyhow::{Context, Result};
use serde::Deserialize;

const BUNDLED: &str = include_str!("../assets/emulators.json");

#[derive(Debug, Deserialize)]
pub struct CatalogFile {
    pub generated: String,
    pub systems: Vec<CatalogSystem>,
    pub emulators: Vec<CatalogEmulator>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogSystem {
    pub id: String,
    pub name: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogEmulator {
    pub id: String,
    pub name: String,
    /// "retroarch" or "standalone"
    pub kind: String,
    /// RetroArch's save folder for this core when "sort saves by core" is on.
    #[serde(default)]
    pub corename: Option<String>,
    pub systems: Vec<String>,
}

pub fn bundled() -> Result<CatalogFile> {
    serde_json::from_str(BUNDLED).context("parse bundled assets/emulators.json")
}

/// An emulator as the UI shows it: from the catalog or a custom one.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EmulatorInfo {
    pub id: String,
    pub name: String,
    pub kind: Kind,
    pub corename: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    RetroArch,
    Standalone,
    Custom,
}

impl Kind {
    pub fn from_catalog(kind: &str) -> Self {
        if kind == "retroarch" {
            Kind::RetroArch
        } else {
            Kind::Standalone
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Kind::RetroArch => "RetroArch core",
            Kind::Standalone => "Standalone",
            Kind::Custom => "Custom",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_catalog_parses_and_covers_the_basics() {
        let c = bundled().unwrap();
        assert!(c.systems.iter().any(|s| s.id == "psx"));
        let snes9x = c.emulators.iter().find(|e| e.id == "ra-snes9x").unwrap();
        assert_eq!(snes9x.corename.as_deref(), Some("Snes9x"));
        assert!(snes9x.systems.contains(&"snes".to_string()));
        let mednafen = c.emulators.iter().find(|e| e.id == "mednafen").unwrap();
        assert!(
            mednafen.systems.len() > 10,
            "multi-system emulators appear once"
        );
        assert!(!c.emulators.iter().any(|e| e.id == "os-shell"));
    }
}
